      "https://revelatedesigns.com/wp-content/uploads/2024/10/c08f0431-f72e-4806-a078-fa169766555d.jpg",
      "https://revelatedesigns.com/wp-content/uploads/2024/10/1e988f0f-51fb-4dc1-92d3-a4e37c2c0780.jpg"
